// Runs the actual inline scripts of index.html in Node's vm with a minimal DOM/FileReader/Blob stub.
// This is NOT browser execution: real rendering, file picker and download behaviour remain untested.
const fs = require('fs'), vm = require('vm'), path = require('path');
const D = process.argv[2], FX = process.argv[3];
const html = fs.readFileSync(path.join(D, 'index.html'), 'utf8');
const scripts = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map(m => m[1]);
const V = fs.readFileSync(FX + '/before-variants.csv', 'utf8'), I = fs.readFileSync(FX + '/before-images.csv', 'utf8'), A = fs.readFileSync(FX + '/after-shopify.csv', 'utf8');
function el(id) { return { id, value: '', files: null, textContent: '', children: [], listeners: {}, get firstChild() { return this.children[0] || null; }, removeChild(c) { this.children.splice(this.children.indexOf(c), 1); }, appendChild(c) { this.children.push(c); }, addEventListener(t, f) { this.listeners[t] = f; } }; }
async function scenario(v, im, opts) {
  const ids = {}; ['v', 'i', 'o', 'm', 'b', 'go', 'rep', 'dl'].forEach(k => ids[k] = el(k));
  ids.o.value = opts.out || 'shopify-products.csv'; ids.m.value = String(opts.max || 0); ids.b.value = '';
  ids.v.files = v === null ? [] : [{ name: 'v.csv', text: v }]; ids.i.files = [{ name: 'i.csv', text: im }];
  const blobs = new Map(); let n = 0; const net = [];
  const sandbox = { document: { getElementById: k => ids[k], createElement: t => ({ tag: t, children: [], appendChild(c) { this.children.push(c); } }) },
    FileReader: function () { this.readAsText = f => setImmediate(() => { this.result = f.text; this.onload(); }); },
    Blob: function (parts, o) { this.text = parts.join(''); this.type = o.type; },
    URL: { createObjectURL: b => { const u = 'blob:' + (++n); blobs.set(u, b); return u; } },
    fetch: () => net.push('fetch'), XMLHttpRequest: function () { net.push('xhr'); }, Promise, JSON, Map, Set, setImmediate };
  sandbox.window = sandbox; vm.createContext(sandbox);
  scripts.forEach(s => vm.runInContext(s, sandbox));
  ids.go.listeners.click(); await new Promise(r => setTimeout(r, 50));
  const links = ids.dl.children.flatMap(p => p.children || []).filter(c => c.tag === 'a');
  return { report: ids.rep.textContent, links: links.map(a => ({ name: a.download, text: blobs.get(a.href).text, type: blobs.get(a.href).type })), notes: ids.dl.children.filter(p => !p.children.length).map(p => p.textContent), net };
}
(async () => {
  const checks = [];
  const c = (name, ok, detail) => checks.push({ name, ok: !!ok, detail });
  let r = await scenario(V, I, {});
  c('fixture_download_byte_identical', r.links.length === 1 && r.links[0].text === A && r.links[0].name === 'shopify-products.csv', r.links.map(l => l.name));
  c('no_network_calls', r.net.length === 0, r.net);
  r = await scenario(V.replace('120.00', '120,00'), I, {});
  c('bad_price_no_download', r.links.length === 0 && /price/.test(r.report) && r.notes.length === 1, r.report.slice(0, 160));
  r = await scenario(V, I, { max: 11, out: 'out' });
  c('split_two_distinct_files', r.links.length === 2 && r.links[0].name === 'out-part1.csv' && r.links[1].name === 'out-part2.csv' && (r.links[0].text + r.links[1].text.split('\n').slice(1).join('\n')) === A, r.links.map(l => l.name));
  r = await scenario(null, I, {});
  c('missing_file_message', /Choose both CSV files/.test(r.report) && r.links.length === 0, r.report);
  r = await scenario(V.replace('barcode', 'ean'), I, {});
  c('missing_column_message', /missing columns/.test(r.report) && r.links.length === 0, r.report);
  const code = scripts.join('\n');
  c('static_no_network_apis', !/\bfetch\(|XMLHttpRequest|WebSocket|sendBeacon|import\(|<script src|<link /.test(html), null);
  c('csp_connect_none', /connect-src 'none'/.test(html) && /default-src 'none'/.test(html), null);
  c('ai_disclosure_en_fr', /autonomous AI agents/.test(html) && /agents d'IA autonomes/.test(html), null);
  c('limits_present', ['historical', 'not</strong> been tested', 'overwritten', 'Status and Published', 'one image per variant'].every(s => html.includes(s)), null);
  c('inline_core_matches_src', code.includes(fs.readFileSync(path.join(D, 'src/core.js'), 'utf8')), null);
  const passed = checks.filter(x => x.ok).length;
  const out = { test: 'index.html inline scripts under Node vm DOM stub', runtime: 'node ' + process.version + '; NOT a real browser', passed, total: checks.length, checks };
  fs.writeFileSync(path.join(D, 'dom-stub-results.json'), JSON.stringify(out, null, 1));
  console.log(JSON.stringify({ passed, total: checks.length, failing: checks.filter(x => !x.ok) }));
  process.exit(passed === checks.length ? 0 : 1);
})();
EOF
